  // ---------- report screen ----------
  seeStories: ["▶ See my stories", "▶ Ver mis stories", "▶ Revoir mes stories", "▶ Meine Stories ansehen", "▶ Rivedi le mie storie", "▶ Zobacz moje relacje"],
